metrics.workdir_dsl:
workspace "Parcel Tracker" "C4 model of the parcel delivery tracking platform" {

    !identifiers hierarchical

    model {

        customer = person "Customer" "A customer who uses the platform to look up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "A parcel delivery tracking platform that lets customers look up shipments and dispatches parcels to couriers" {

            webPortal = container "Web Portal" "The web portal where customers look up shipments" "Web application"
            dispatchService = container "Dispatch Service" "The service that assigns parcels to couriers" "Service"
            pricingLibrary = container "Pricing Rules Library" "A shared library that computes delivery prices from weight and zone" "Software library" "Software Library"
            database = container "Database" "Stores shipments and dispatch records" "Database" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An external email delivery provider operated by a different organization" "External"

        customer -> parcelTracker.webPortal "looks up the status of their parcels" "Web browser"
        parcelTracker.webPortal -> parcelTracker.pricingLibrary "embeds" "In-process"
        parcelTracker.dispatchService -> parcelTracker.pricingLibrary "embeds" "In-process"
        parcelTracker.dispatchService -> emailProvider "sends customer notification emails through" "SMTP"
        parcelTracker.webPortal -> parcelTracker.database "reads shipment records from" "SQL"
        parcelTracker.dispatchService -> parcelTracker.database "writes dispatch records to" "SQL"
    }

    views {

        systemContext parcelTracker "SystemContext" {
            include *
            autoLayout
            title "System Context for Parcel Tracker"
        }

        container parcelTracker "Containers" {
            include *
            autoLayout
            title "Containers for Parcel Tracker"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Software Library" {
                shape Hexagon
            }
        }
    }

    configuration {
        scope softwareSystem
    }
}
